// Enriquecer listings de Apify con su barrio (punto-en-polígono) y mapear a la tabla
const geo = $('Fetch Barrios').first().json;
const feats = (geo && geo.features) || [];

function ringContains(ring, lng, lat) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    const intersect = ((yi > lat) !== (yj > lat)) &&
      (lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}
function polyContains(coords, lng, lat) {
  if (!coords.length) return false;
  if (!ringContains(coords[0], lng, lat)) return false;      // fuera del anillo exterior
  for (let k = 1; k < coords.length; k++) {                   // dentro de un hueco
    if (ringContains(coords[k], lng, lat)) return false;
  }
  return true;
}
function findBarrio(lng, lat) {
  for (const f of feats) {
    const g = f.geometry;
    if (!g) continue;
    if (g.type === 'Polygon' && polyContains(g.coordinates, lng, lat)) return f.properties;
    if (g.type === 'MultiPolygon') {
      for (const poly of g.coordinates) if (polyContains(poly, lng, lat)) return f.properties;
    }
  }
  return null;
}

// Aplanar la salida de Apify (puede venir como items o como un array anidado)
const raw = $input.all().map(i => i.json);
const listings = [];
for (const x of raw) { if (Array.isArray(x)) listings.push(...x); else listings.push(x); }

const now = new Date().toISOString();
const records = listings
  .filter(l => l && (l.adid || l.propertyCode))
  .map(l => {
    const mc = l.moreCharacteristics || {};
    const ci = l.contactInfo || {};
    const ub = l.ubication || {};
    const lat = Number(ub.latitude);
    const lng = Number(ub.longitude);
    const barrio = (isFinite(lat) && isFinite(lng)) ? findBarrio(lng, lat) : null;
    const userType = (ci.userType || '').toLowerCase();
    return {
      idealista_id: String(l.adid || l.propertyCode),
      operacion: (l.operation === 'rent' || l.operation === 'alquiler') ? 'alquiler' : 'venta',
      tipo: l.propertyType || (l.detailedType && l.detailedType.typology) || null,
      codbarrio: barrio ? barrio.codbarrio : null,
      barrio: barrio ? barrio.nombre : null,
      lat: isFinite(lat) ? lat : null,
      lng: isFinite(lng) ? lng : null,
      precio: l.price != null ? Number(l.price) : null,
      metros: (l.size != null ? Number(l.size) : (mc.constructedArea != null ? Number(mc.constructedArea) : null)),
      habitaciones: l.rooms != null ? Number(l.rooms) : (mc.roomNumber != null ? Number(mc.roomNumber) : null),
      banos: l.bathrooms != null ? Number(l.bathrooms) : (mc.bathNumber != null ? Number(mc.bathNumber) : null),
      planta: l.floor || mc.floor || null,
      ascensor: (mc.lift != null) ? Boolean(mc.lift) : null,
      estado_conservacion: mc.status || null,
      anunciante: userType.includes('profess') ? 'agencia' : (userType ? 'particular' : null),
      agencia_nombre: ci.commercialName || null,
      activo: true,
      fecha_ultima_vista: now
    };
  })
  .filter(r => r.precio && r.metros);

return [{ json: { count: records.length, records } }];
